function evidence = f90_xrobo09_extract_reference_evidence(modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XROBO09_EXTRACT_REFERENCE_EVIDENCE One-session official-scenario replay.
% This function extracts simulation evidence only. It contains no score
% thresholds, weights, aggregation rules, caps, or admission decisions.

arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios (1,1) string
    evaluatorAssetRoot (1,1) string
end
assert(isfile(officialScenarios), "SimuVerity:F90:XROBO09:OfficialScenarios", ...
    "Official scenarios are missing.");
assert(isfolder(evaluatorAssetRoot), "SimuVerity:F90:XROBO09:ReferenceAssetRoot", ...
    "Evaluator asset root is missing.");
bundleRoot = string(fileparts(modelPath));
referenceRoot = fullfile(bundleRoot, "MarineVessel");
modelRoot = fullfile(referenceRoot, "Model");
dataRoot = fullfile(referenceRoot, "DataFile");
scenarioRoot = fullfile(referenceRoot, "Scenario", "ExportedScenario");
official = jsondecode(fileread(officialScenarios));
modelFile = modelPath;
assert(strcmpi(localFilePresence(modelFile), string("present")), ...
    "SimuVerity:F90:XROBO09:ModelBinding", "Pinned root-model binding mismatch.");
localValidatePinnedFiles(referenceRoot, official);

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XROBO09:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
outDir = outputDir;
assert(~isfolder(outDir), "SimuVerity:F90:XROBO09:OutputReuse", ...
    "Evidence output already exists for GenerationRunId %s.", generationRunId);
mkdir(outDir);

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XROBO09:Isolation", ...
    "Isolated cache and codegen folders are required.");
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
addpath(modelRoot, "-begin");
addpath(dataRoot, "-begin");
addpath(scenarioRoot, "-begin");
addpath(fullfile(referenceRoot, "Helper"), "-begin");
originalDirectory = pwd;
directoryCleanup = onCleanup(@() cd(originalDirectory)); %#ok<NASGU>
cd(referenceRoot);

evidence = struct( ...
    "schema", "simuverity.f90-xrobo09-evidence.v1", ...
    "task_id", "F90-XROBO-09", ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));

model = "";
try
    modelHandle = load_system(modelFile);
    model = string(get_param(modelHandle, "Name"));
    cleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>
    evidence.load_pass = true;

    localRunParameterScripts(dataRoot);
    scenarioVariables = localScenarioVariableUnion( ...
        referenceRoot, official.scenarios);
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "SignalLogging", "off", ...
        "SaveOutput", "off", ...
        "FastRestart", "off");
    localDisableVisualizationOnlyBlocks(model);
    localSetAutonomousFlags(model);
    localInstallMeasurementTaps(model);

    localApplyScenario(model, referenceRoot, official.scenarios(1), ...
        scenarioVariables);
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(model);

    localApplyScenario(model, referenceRoot, official.scenarios(1), ...
        scenarioVariables);
    set_param(model, "StopTime", "1");
    smoke = sim(model, "ReturnWorkspaceOutputs", "on");
    localValidateSmoke(smoke);
    evidence.nominal_smoke_pass = true;
    clear smoke

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).requested_inputs = scenario;
        try
            rows(k).applied_parameters = localApplyScenario( ...
                model, referenceRoot, scenario, scenarioVariables);
            set_param(model, "StopTime", ...
                sprintf("%.17g", double(scenario.stop_time_s)));
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut, ...
                double(scenario.stop_time_s));
            rows(k) = localFinalizeScenario(rows(k), outputs, scenario);
            clear simOut
        catch ME
            rows(k).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
catch ME
    evidence.errors.session = localError(ME);
end

localCloseModel(model);
evidence.model_closed_without_save = ~bdIsLoaded(model);
evidence.root_model_file_presence_after = localFilePresence(modelFile);
evidence.binding_preserved = strcmpi(evidence.root_model_file_presence_after, ...
    string("present"));
evidence.finished_at = localNow;
validCount = 0;
if ~isempty(evidence.scenarios)
    validCount = sum([evidence.scenarios.valid]);
end
evidence.evidence_complete = evidence.load_pass && evidence.update_pass && ...
    evidence.compile_pass && evidence.nominal_smoke_pass && ...
    evidence.binding_preserved && numel(evidence.scenarios) == numel(official.scenarios) && ...
    validCount == numel(official.scenarios);
evidencePath = fullfile(outDir, "evidence.json");
localWriteJson(evidencePath, evidence);
fprintf("F90_XROBO09_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d binding=%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    evidence.nominal_smoke_pass, validCount, ...
    numel(evidence.scenarios), evidence.binding_preserved, evidencePath);
end

function localDisableVisualizationOnlyBlocks(model)
% The official UAV Scenario Scope is a pure visualization sink.  It opens
% a desktop figure from resetImpl and cannot compile in a headless batch
% worker.  Comment it in memory only; scenario generation, traffic ground
% truth, assessment, planning, control and vessel dynamics remain intact.
scope = Simulink.ID.getHandle(string(model) + ":2325");
assert(scope > 0, "SimuVerity:F90:XROBO09:ScenarioScope", ...
    "Official visualization-only scenario scope is missing.");
set_param(scope, "Commented", "on");
end

function localValidatePinnedFiles(referenceRoot, official)
names = ["DataVesselPlatform.m", "DataInitialCondition.m", ...
    "DataSampleTime.m", "DataGuidance.m"];
bindings = [ ...
    "present"; ...
    "present"; ...
    "present"; ...
    "present"];
for k = 1:numel(names)
    name = names(k);
    path = fullfile(referenceRoot, "DataFile", name);
    assert(strcmpi(localFilePresence(path), bindings(k)), ...
        "SimuVerity:F90:XROBO09:ParameterBinding", ...
        "Pinned parameter-file binding mismatch: %s", name);
end
for k = 1:numel(official.scenarios)
    scenario = official.scenarios(k);
    path = fullfile(referenceRoot, char(scenario.scenario_mat));
    assert(isfile(path), ...
        "SimuVerity:F90:XROBO09:ScenarioBinding", ...
        "Pinned scenario binding mismatch: %s", scenario.id);
end
end

function localRunParameterScripts(dataRoot)
names = ["DataVesselPlatform.m", "DataInitialCondition.m", ...
    "DataSampleTime.m", "DataGuidance.m"];
for k = 1:numel(names)
    path = fullfile(dataRoot, names(k));
    command = "run('" + replace(string(path), "'", "''") + "')";
    evalin("base", command);
end
end

function names = localScenarioVariableUnion(referenceRoot, scenarios)
names = strings(0, 1);
for k = 1:numel(scenarios)
    path = fullfile(referenceRoot, char(scenarios(k).scenario_mat));
    found = string(who("-file", path));
    names = union(names, found(:), "stable");
end
end

function applied = localApplyScenario(model, referenceRoot, scenario, names)
for k = 1:numel(names)
    evalin("base", "clear " + names(k));
end
scenarioPath = fullfile(referenceRoot, char(scenario.scenario_mat));
evalin("base", "load('" + ...
    replace(string(scenarioPath), "'", "''") + "')");
waypoints = double(scenario.Waypoints_m);
assignin("base", "waypoints_m", waypoints);
assignin("base", "StopTime", double(scenario.stop_time_s));
assignin("base", "xlimits", [min(waypoints(:, 1)) - 80, ...
    max(waypoints(:, 1)) + 80]);
assignin("base", "ylimits", [min(waypoints(:, 2)) - 80, ...
    max(waypoints(:, 2)) + 180]);
localSetValueBySid(model, "2255", double(scenario.DesiredSpeed_mps));
localSetValueBySid(model, "19", double(scenario.CurrentSpeed_mps));
localSetValueBySid(model, "20", double(scenario.CurrentDirection_deg));
localSetAutonomousFlags(model);
applied = struct( ...
    "scenario_mat", string(scenario.scenario_mat), ...
    "waypoints_m", waypoints, ...
    "desired_speed_mps", double(scenario.DesiredSpeed_mps), ...
    "current_speed_mps", double(scenario.CurrentSpeed_mps), ...
    "current_direction_deg", double(scenario.CurrentDirection_deg), ...
    "stop_time_s", double(scenario.stop_time_s));
end

function localSetAutonomousFlags(model)
localSetValueBySid(model, "1446", 0); % remote control off
localSetValueBySid(model, "1850", 1); % run
localSetValueBySid(model, "1911", 1); % waypoint following
localSetValueBySid(model, "2027", 0); % no reset
localSetValueBySid(model, "2198", 1); % collision avoidance
end

function localSetValueBySid(model, sid, value)
handle = Simulink.ID.getHandle(string(model) + ":" + string(sid));
assert(handle > 0, "SimuVerity:F90:XROBO09:BlockSid", ...
    "Required source block SID is missing: %s", sid);
set_param(handle, "Value", sprintf("%.17g", double(value)));
end

function localInstallMeasurementTaps(model)
% VesselState: x,y,z,u,v,w,roll,pitch,yaw,p,q,r,speed,course
localTapFeeders(model, ...
    ["1138","1139","1140","1132","1133","1134", ...
     "1141","1142","1143","1135","1136","1137","1144","2423"], ...
    ["x","y","z","u","v","w","roll","pitch","yaw", ...
     "p","q","r","speed","course"]);

% Guidance and planning.
localTapSourceBySid(model, "2255", "desired_speed");
localTapFeeders(model, ...
    ["1402","1412","1413","1414","1415","1940"], ...
    ["desired_yaw","reference_x","reference_y", ...
     "next_reference_x","next_reference_y","mode"]);

% Requested and delivered propulsion.
localTapFeeders(model, ...
    ["2249","82","1366","1367","359"], ...
    ["desired_thrust","desired_moment","left_prop", ...
     "right_prop","delivered_force_moment"]);

% Traffic ground truth and encounter assessment.
localTapFeeders(model, ...
    ["2100","2105","2111","2116","2134","2151","2143","2152", ...
     "2376","2377","2378","2493","2494","2495","2497","2496", ...
     "2387","2388","2389","2539","2540","2541","2543","2542"], ...
    ["traffic1_position","traffic1_velocity","traffic1_yaw", ...
     "traffic1_tcpa","traffic1_dcpa","traffic1_collision", ...
     "traffic1_bearing","traffic1_sector", ...
     "traffic2_position","traffic2_velocity","traffic2_yaw", ...
     "traffic2_tcpa","traffic2_dcpa","traffic2_collision", ...
     "traffic2_bearing","traffic2_sector", ...
     "traffic3_position","traffic3_velocity","traffic3_yaw", ...
     "traffic3_tcpa","traffic3_dcpa","traffic3_collision", ...
     "traffic3_bearing","traffic3_sector"]);

% Applied current and autonomous-state flags.
localTapFeeders(model, ["1237","1238"], ...
    ["current_speed","current_direction"]);
localTapSourceBySid(model, "1850", "run_flag");
localTapSourceBySid(model, "2198", "avoidance_enabled");
end

function localTapFeeders(model, sids, variables)
assert(numel(sids) == numel(variables));
for k = 1:numel(sids)
    localTapFeederBySid(model, sids(k), variables(k));
end
end

function localTapFeederBySid(model, sid, variable)
destination = Simulink.ID.getHandle(string(model) + ":" + sid);
assert(destination > 0, "SimuVerity:F90:XROBO09:TapSid", ...
    "Required tap destination SID is missing: %s", sid);
ports = get_param(destination, "PortHandles");
assert(~isempty(ports.Inport) && ports.Inport(1) > 0, ...
    "SimuVerity:F90:XROBO09:TapInput", ...
    "Required tap destination has no input port: %s", sid);
line = get_param(ports.Inport(1), "Line");
assert(line > 0, "SimuVerity:F90:XROBO09:TapLine", ...
    "Required tap destination is not connected: %s", sid);
sourcePort = get_param(line, "SrcPortHandle");
assert(sourcePort > 0, "SimuVerity:F90:XROBO09:TapSource", ...
    "Required tap source is missing: %s", sid);
parent = string(get_param(destination, "Parent"));
localAddTap(parent, sourcePort, variable);
end

function localTapSourceBySid(model, sid, variable)
source = Simulink.ID.getHandle(string(model) + ":" + sid);
assert(source > 0, "SimuVerity:F90:XROBO09:TapSid", ...
    "Required tap source SID is missing: %s", sid);
ports = get_param(source, "PortHandles");
assert(~isempty(ports.Outport) && ports.Outport(1) > 0, ...
    "SimuVerity:F90:XROBO09:TapOutput", ...
    "Required source has no output port: %s", sid);
parent = string(get_param(source, "Parent"));
localAddTap(parent, ports.Outport(1), variable);
end

function localAddTap(parent, sourcePort, variable)
sink = parent + "/F90 " + variable + " Tap";
assert(getSimulinkBlockHandle(sink) < 0, ...
    "SimuVerity:F90:XROBO09:TapCollision", ...
    "Temporary measurement tap already exists: %s", sink);
add_block("simulink/Sinks/To Workspace", sink, ...
    "VariableName", "f90_" + variable, ...
    "SaveFormat", "Timeseries", ...
    "MaxDataPoints", "inf");
sinkPorts = get_param(sink, "PortHandles");
add_line(parent, sourcePort, sinkPorts.Inport(1), "autorouting", "on");
end

function localValidateSmoke(simOut)
required = { ...
    "f90_x", 1; "f90_y", 1; "f90_u", 1; "f90_yaw", 1; ...
    "f90_desired_speed", 1; "f90_desired_yaw", 1; ...
    "f90_left_prop", 1; "f90_right_prop", 1; ...
    "f90_traffic1_position", 2; "f90_traffic1_dcpa", 1; ...
    "f90_mode", 1; "f90_current_speed", 1};
for k = 1:size(required, 1)
    localWorkspaceTimeseries(simOut, required{k, 1}, required{k, 2});
end
end

function outputs = localExtractOutputs(simOut, stopTime)
sampleTime = 0.1;
time = (0:sampleTime:stopTime)';
if time(end) < stopTime - sampleTime / 100
    time(end + 1, 1) = stopTime; %#ok<AGROW>
end

vessel = [ ...
    localSample(simOut, "x", time, "linear"), ...
    localSample(simOut, "y", time, "linear"), ...
    localSample(simOut, "z", time, "linear"), ...
    localSample(simOut, "u", time, "linear"), ...
    localSample(simOut, "v", time, "linear"), ...
    localSample(simOut, "w", time, "linear"), ...
    localSample(simOut, "roll", time, "linear"), ...
    localSample(simOut, "pitch", time, "linear"), ...
    localSample(simOut, "yaw", time, "linear"), ...
    localSample(simOut, "p", time, "linear"), ...
    localSample(simOut, "q", time, "linear"), ...
    localSample(simOut, "r", time, "linear"), ...
    localSample(simOut, "speed", time, "linear"), ...
    localSample(simOut, "course", time, "linear")];
guidance = [ ...
    localSample(simOut, "desired_speed", time, "previous"), ...
    localSample(simOut, "desired_yaw", time, "previous"), ...
    localSample(simOut, "reference_x", time, "previous"), ...
    localSample(simOut, "reference_y", time, "previous"), ...
    localSample(simOut, "next_reference_x", time, "previous"), ...
    localSample(simOut, "next_reference_y", time, "previous"), ...
    localSample(simOut, "mode", time, "previous")];
delivered = localSample(simOut, "delivered_force_moment", ...
    time, "linear");
assert(size(delivered, 2) >= 6, "SimuVerity:F90:XROBO09:ThrustChannels", ...
    "Delivered force/moment tap has fewer than six channels.");
propulsion = [ ...
    localSample(simOut, "desired_thrust", time, "previous"), ...
    localSample(simOut, "desired_moment", time, "previous"), ...
    localSample(simOut, "left_prop", time, "previous"), ...
    localSample(simOut, "right_prop", time, "previous"), ...
    delivered(:, 1), delivered(:, 6)];
traffic = [ ...
    localTraffic(simOut, 1, time), ...
    localTraffic(simOut, 2, time), ...
    localTraffic(simOut, 3, time)];
operating = [ ...
    localSample(simOut, "current_speed", time, "previous"), ...
    localSample(simOut, "current_direction", time, "previous"), ...
    localSample(simOut, "run_flag", time, "previous"), ...
    localSample(simOut, "avoidance_enabled", time, "previous")];
outputs = struct( ...
    "time_s", time, ...
    "vessel_state", vessel, ...
    "guidance_state", guidance, ...
    "propulsion_state", propulsion, ...
    "traffic_state", traffic, ...
    "operating_state", operating);
end

function data = localTraffic(simOut, index, time)
prefix = "traffic" + string(index) + "_";
position = localSample(simOut, prefix + "position", time, "linear");
velocity = localSample(simOut, prefix + "velocity", time, "linear");
assert(size(position, 2) >= 2 && size(velocity, 2) >= 2, ...
    "SimuVerity:F90:XROBO09:TrafficChannels", ...
    "Traffic position or velocity has fewer than two channels.");
data = [position(:, 1:2), velocity(:, 1:2), ...
    localSample(simOut, prefix + "yaw", time, "linear"), ...
    localSample(simOut, prefix + "tcpa", time, "previous"), ...
    localSample(simOut, prefix + "dcpa", time, "previous"), ...
    localSample(simOut, prefix + "collision", time, "previous"), ...
    localSample(simOut, prefix + "bearing", time, "previous"), ...
    localSample(simOut, prefix + "sector", time, "previous")];
end

function data = localSample(simOut, variable, time, method)
series = localWorkspaceTimeseries(simOut, "f90_" + variable, 1);
sourceTime = double(series.Time(:));
sourceData = localTimeFirstData(series.Data, numel(sourceTime));
[sourceTime, uniqueIndex] = unique(sourceTime, "last");
sourceData = sourceData(uniqueIndex, :);
assert(~isempty(sourceTime), "SimuVerity:F90:XROBO09:EmptyTimeseries", ...
    "Timeseries is empty: %s", variable);
if numel(sourceTime) == 1
    % Constant and dashboard-backed source blocks can legitimately emit a
    % single sample.  Replicate that measured value over the requested
    % evidence grid instead of asking interp1 for a degenerate grid.
    data = repmat(sourceData(1, :), numel(time), 1);
else
    data = interp1(sourceTime, sourceData, time, method, "extrap");
end
end

function data = localTimeFirstData(raw, timeCount)
data = double(squeeze(raw));
if isvector(data)
    data = data(:);
elseif size(data, 1) ~= timeCount && size(data, 2) == timeCount
    data = data.';
elseif size(data, 1) ~= timeCount && size(data, ndims(data)) == timeCount
    order = [ndims(data), 1:(ndims(data) - 1)];
    data = permute(data, order);
    data = reshape(data, timeCount, []);
end
assert(size(data, 1) == timeCount, "SimuVerity:F90:XROBO09:TimeseriesShape", ...
    "Timeseries data cannot be aligned with its time vector.");
data = reshape(data, timeCount, []);
end

function series = localWorkspaceTimeseries(simOut, name, minimumChannels)
try
    series = simOut.get(char(name));
catch
    series = [];
end
assert(isa(series, "timeseries"), "SimuVerity:F90:XROBO09:MissingTimeseries", ...
    "Required workspace Timeseries is missing: %s", name);
data = localTimeFirstData(series.Data, numel(series.Time));
assert(size(data, 2) >= minimumChannels, ...
    "SimuVerity:F90:XROBO09:TimeseriesChannels", ...
    "Timeseries %s has too few channels.", name);
end

function row = localFinalizeScenario(row, outputs, scenario)
allValues = [outputs.time_s; outputs.vessel_state(:); ...
    outputs.guidance_state(:); outputs.propulsion_state(:); ...
    outputs.traffic_state(:); outputs.operating_state(:)];
currentError = max(abs(outputs.operating_state(:, 1) - ...
    double(scenario.CurrentSpeed_mps)));
directionError = max(abs(outputs.operating_state(:, 2) - ...
    deg2rad(double(scenario.CurrentDirection_deg))));
speedReferenceError = max(abs(outputs.guidance_state(:, 1) - ...
    double(scenario.DesiredSpeed_mps)));
trafficMovement = max(vecnorm(diff(outputs.traffic_state(:, 1:2), ...
    1, 1), 2, 2));
row.simulation_pass = true;
row.scenario_application_pass = currentError <= 1e-9 && ...
    directionError <= 1e-9 && speedReferenceError <= 1e-9 && ...
    trafficMovement > 1e-6;
row.required_evidence_pass = all(isfinite(allValues)) && ...
    numel(outputs.time_s) >= 100 && ...
    abs(outputs.time_s(1)) <= 1e-12 && ...
    outputs.time_s(end) >= double(scenario.stop_time_s) - 1e-6;
row.valid = row.required_evidence_pass && ...
    row.scenario_application_pass;
row.sample_count = numel(outputs.time_s);
row.start_time_s = outputs.time_s(1);
row.end_time_s = outputs.time_s(end);
row.application_errors = struct( ...
    "current_speed_abs_error_mps", currentError, ...
    "current_direction_abs_error_rad", directionError, ...
    "desired_speed_abs_error_mps", speedReferenceError, ...
    "traffic1_max_step_motion_m", trafficMovement);
row.outputs = outputs;
row.error = struct;
end

function audit = localStaticAudit(model)
requiredSids = ["62","2929","425","2862","547","525","357", ...
    "1918","2096","1404","1392","1251"];
present = false(size(requiredSids));
for k = 1:numel(requiredSids)
    try
        present(k) = Simulink.ID.getHandle( ...
            string(model) + ":" + requiredSids(k)) > 0;
    catch
        present(k) = false;
    end
end
audit = struct( ...
    "vessel_platform_present", present(1), ...
    "closed_loop_controller_present", present(2), ...
    "six_dof_core_present", present(3), ...
    "hydrodynamic_core_present", present(4), ...
    "hydrostatic_core_present", present(5), ...
    "current_crossflow_core_present", present(6), ...
    "twin_propeller_thrust_core_present", present(7), ...
    "traffic_ground_truth_assessment_present", ...
        present(8) && present(9), ...
    "collision_avoidance_planning_present", present(10), ...
    "waypoint_guidance_present", present(11), ...
    "control_allocation_present", present(12), ...
    "controller_to_vessel_connected", ...
        localPortConnected(model, "2929", 1, "62", 1), ...
    "vessel_feedback_to_controller_connected", ...
        localPortConnected(model, "62", 1, "2929", 3), ...
    "scenario_to_controller_connected", ...
        localPortConnected(model, "2014", 1, "2929", 2), ...
    "environment_to_vessel_connected", ...
        localPortConnected(model, "1370", 1, "62", 3));
end

function connected = localPortConnected(model, sourceSid, sourceIndex, ...
        destinationSid, destinationIndex)
connected = false;
try
    source = Simulink.ID.getHandle(string(model) + ":" + sourceSid);
    destination = Simulink.ID.getHandle( ...
        string(model) + ":" + destinationSid);
    sourcePorts = get_param(source, "PortHandles");
    destinationPorts = get_param(destination, "PortHandles");
    line = get_param(sourcePorts.Outport(sourceIndex), "Line");
    destinations = get_param(line, "DstPortHandle");
    connected = any(destinations == ...
        destinationPorts.Inport(destinationIndex));
catch
    connected = false;
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "requested_inputs", struct, ...
    "applied_parameters", struct, ...
    "simulation_wall_clock_s", NaN, ...
    "simulation_pass", false, ...
    "scenario_application_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "sample_count", 0, ...
    "start_time_s", NaN, ...
    "end_time_s", NaN, ...
    "application_errors", struct, ...
    "outputs", struct, ...
    "error", struct);
end

function result = localError(ME)
result = struct( ...
    "identifier", string(ME.identifier), ...
    "message", string(ME.message), ...
    "stack", string({ME.stack.name}));
end

function localCloseModel(model)
try
    if bdIsLoaded(model)
        close_system(model, 0);
    end
catch
end
end

function localWriteJson(path, value)
text = jsonencode(value, PrettyPrint=true);
fid = fopen(path, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XROBO09:EvidenceWrite", ...
    "Unable to open evidence path.");
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, text, "char");
end

function binding = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
binding = "present";
end

function value = localNow
value = string(datetime("now", "TimeZone", "UTC", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"));
end
